    },
    {
      "type": "vis",
      "grid": { "x": 0, "y": 3, "w": 16, "h": 6 },
      "config": {
        "type": "metric",
        "title": "Total requests",
        "data_source": { "type": "esql", "query": "FROM kibana_sample_data_logs | STATS requests = COUNT(*)" },
        "metrics": [ { "type": "primary", "column": "requests" } ],
        "sampling": 1,
        "ignore_global_filters": false
      }
    },
    {
      "type": "vis",
      "grid": { "x": 16, "y": 3, "w": 16, "h": 6 },
      "config": {
        "type": "metric",
        "title": "Unique client IPs",
        "data_source": { "type": "esql", "query": "FROM kibana_sample_data_logs | STATS clients = COUNT_DISTINCT(clientip)" },
        "metrics": [ { "type": "primary", "column": "clients" } ],
        "sampling": 1,
        "ignore_global_filters": false
      }
    },
    {
      "type": "vis",
      "grid": { "x": 32, "y": 3, "w": 16, "h": 6 },
      "config": {
        "type": "metric",
        "title": "5xx responses",
        "data_source": { "type": "esql", "query": "FROM kibana_sample_data_logs | WHERE response.keyword >= \"500\" AND response.keyword <= \"599\" | STATS errors = COUNT(*)" },
        "metrics": [ { "type": "primary", "column": "errors" } ],
        "sampling": 1,
        "ignore_global_filters": false
      }
    },
    {
      "type": "vis",
      "grid": { "x": 0, "y": 9, "w": 48, "h": 10 },
      "config": {
        "type": "xy",
        "title": "Requests over time",
        "axis": {
          "x": { "scale": "ordinal", "labels": { "orientation": "horizontal" }, "title": { "visible": false } },
          "y": { "anchor": "start", "scale": "linear", "labels": { "orientation": "horizontal" }, "title": { "visible": true } }
        },
        "layers": [
          {
            "type": "line",
            "data_source": {
              "type": "esql",
              "query": "FROM kibana_sample_data_logs | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
            },
            "ignore_global_filters": false,
            "sampling": 1,
            "x": { "column": "BUCKET(@timestamp, 75, ?_tstart, ?_tend)" },
            "y": [ { "axis_id": "y", "column": "count" } ]
          }
        ],
        "legend": { "placement": "outside", "position": "right", "visibility": "hidden" }
      }
    }
  ]
}
EOF
curl -sS -H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H "kbn-xsrf: true" -H "Content-Type: application/json" -X POST "$KIBANA_URL/api/dashboards" --data-binary @$S/dash.json | head -c 1200

